package action

// Action represents a single compact action generated by an LLM provider.
// Short JSON keys minimize output tokens; use FormatVerbose / ToVerboseMap
// when emitting human-readable logs or UI payloads.
type Action struct {
	Seq    int    `json:"i"`           // Sequence ID (1-based)
	Code   string `json:"a"`           // Compact action code (e.g. "mm", "cl", "tp")
	X      int    `json:"x,omitempty"` // X coordinate / horizontal delta
	Y      int    `json:"y,omitempty"` // Y coordinate / vertical delta / scroll amount
	Dur    int    `json:"d,omitempty"` // Duration in seconds (for wait/nop)
	Text   string `json:"t,omitempty"` // Text to type (for printString)
	Key    string `json:"k,omitempty"` // Key name (for keyTap, keyDown, keyUp)
	Range  []int  `json:"r,omitempty"` // 1-based inclusive [start, end] range (for repeat)
	Repeat int    `json:"n,omitempty"` // Repeat count (for repeat)
}

// ExecutionResult captures control-flow signals returned by an action handler.
type ExecutionResult struct {
	StopIteration bool
}

// ExecutionContext provides shared state to an action handler during execution.
type ExecutionContext struct {
	Actions  []Action
	Index    int
	Executor *Executor
	Depth    int // Nesting depth for repeat guard
}

// HandlerFunc executes a single action within an ExecutionContext.
type HandlerFunc func(ctx *ExecutionContext, a *Action) (ExecutionResult, error)

// Definition describes a registered action type, its compact wire code,
// verbose human-readable name, prompt metadata, and execution handler.
type Definition struct {
	Code        string
	Name        string
	Description string
	ExampleJSON string
	Execute     HandlerFunc
	FormatArgs  func(a *Action) string
}

// IsStop reports whether this action signals stopping the current iteration.
func (a Action) IsStop() bool {
	return DefaultRegistry().ResolveCode(a.Code) == CodeStopIteration
}
